**src/server.js:**
```js
import app from './app.js';
import { env } from './config/env.js';
import prisma from './database/prisma.js';

const server = app.listen(env.port, () => {
  console.log(`[contract-guard] API listening on http://localhost:${env.port} (${env.nodeEnv})`);
});

async function shutdown(signal) {
  console.log(`[contract-guard] ${signal} received, shutting down...`);
  server.close(async () => {
    await prisma.$disconnect().catch(() => {});
    process.exit(0);
  });
  // Fallback force-exit
  setTimeout(() => process.exit(1), 10_000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

**prisma/schema.prisma:** as per the blueprint. Prisma syntax details:
- `@default(uuid())` fine.
- String[] fine on postgres.
- Json fine.
- Relation fields with array names need @relation(name) on both sides for multiple relations between the same models: Service ↔ ApiVersion single; ApiVersion ↔ AnalysisRun twice ("ProposedVersion" and "BaselineVersion") — need @relation on both sides; Service ↔ ConsumerDependency twice — named both sides.
- Optional relations: baselineVersionId String? and baselineVersion ApiVersion? @relation(...). For a single optional relation, @relation(name) on both sides is fine even without name; but since there are two relations between the same pair, name is required on both sides of both pairs.

Let me write the schema exactly:

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum SpecFormat {
  YAML
  JSON
}

enum VersionStatus {
  PROPOSED
  PUBLISHED
}

enum RunStatus {
  RUNNING
  COMPLETED
  FAILED
}

enum Classification {
  BREAKING
  WARNING
  NON_BREAKING
  UNKNOWN
}

enum PublishOutcome {
  PUBLISHED
  BLOCKED
  OVERRIDDEN
}

model Service {
  id          String   @id @default(uuid())
  name        String   @unique
  owner       String
  description String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  apiVersions    ApiVersion[]
  consumerDeps   ConsumerDependency[] @relation("ConsumerService")
  providerDeps   ConsumerDependency[] @relation("ProviderService")
}

model ApiVersion {
  id           String        @id @default(uuid())
  serviceId    String
  versionLabel String
  specContent  String
  parsedSpec   Json
  format       SpecFormat
  status       VersionStatus @default(PROPOSED)
  publishedAt  DateTime?
  createdAt    DateTime      @default(now())

  service         Service          @relation(fields: [serviceId], references: [id], onDelete: Cascade)
  proposedRuns    AnalysisRun[]    @relation("ProposedVersion")
  baselineRuns    AnalysisRun[]    @relation("BaselineVersion")
  publishAttempts PublishAttempt[]

  @@unique([serviceId, versionLabel])
  @@index([serviceId])
}

model ConsumerDependency {
  id                String   @id @default(uuid())
  consumerServiceId String
  providerServiceId String
  method            String
  path              String
  sends             String[] @default([])
  reads             String[] @default([])
  createdAt         DateTime @default(now())
  updatedAt         DateTime @updatedAt

  consumerService  Service @relation("ConsumerService", fields: [consumerServiceId], references: [id], onDelete: Cascade)
  providerService  Service @relation("ProviderService", fields: [providerServiceId], references: [id], onDelete: Cascade)
  impactFindings   ImpactFinding[]

  @@unique([consumerServiceId, providerServiceId, method, path])
  @@index([providerServiceId])
}

model AnalysisRun {
  id                String    @id @default(uuid())
  proposedVersionId String
  baselineVersionId String?
  status            RunStatus @default(RUNNING)
  summary           Json?
  createdAt         DateTime  @default(now())
  completedAt       DateTime?

  proposedVersion ApiVersion            @relation("ProposedVersion", fields: [proposedVersionId], references: [id], onDelete: Cascade)
  baselineVersion ApiVersion?           @relation("BaselineVersion", fields: [baselineVersionId], references: [id], onDelete: SetNull)
  changes         CompatibilityChange[]
  publishAttempts PublishAttempt[]

  @@index([proposedVersionId])
}

model CompatibilityChange {
  id             String         @id @default(uuid())
  analysisRunId  String
  changeType     String
  method         String?
  path           String?
  fieldPath      String?
  classification Classification
  beforeValue    Json?
  afterValue     Json?
  reason         String

  analysisRun    AnalysisRun       @relation(fields: [analysisRunId], references: [id], onDelete: Cascade)
  impactFindings ImpactFinding[]

  @@index([analysisRunId])
}

model ImpactFinding {
  id           String   @id @default(uuid())
  changeId     String
  dependencyId String
  reason       String
  createdAt    DateTime @default(now())

  change     CompatibilityChange @relation(fields: [changeId], references: [id], onDelete: Cascade)
  dependency ConsumerDependency  @relation(fields: [dependencyId], references: [id], onDelete: Cascade)

  @@unique([changeId, dependencyId])
  @@index([dependencyId])
}

model PublishAttempt {
  id            String         @id @default(uuid())
  versionId     String
  analysisRunId String?
  outcome       PublishOutcome
  reason        String?
  approver      String?
  overrideRationale String?
  createdAt     DateTime       @default(now())

  version     ApiVersion   @relation(fields: [versionId], references: [id], onDelete: Cascade)
  analysisRun AnalysisRun? @relation(fields: [analysisRunId], references: [id], onDelete: SetNull)

  @@index([versionId])
}
```

Prisma validation: `prisma validate` checks the syntax and relation consistency. Note: for optional relations with onDelete SetNull — fine. One gotcha: Prisma requires that when one side of a relation is optional, the scalar field is also optional — satisfied.

**tests/:** node --test. Two test files:
- tests/app.test.js — import createApp/app, use node:http to start a server on an ephemeral port, or... supertest without express. I'll use the http server: `const server = app.listen(0)`, then fetch to `http://127.0.0.1:${port}`. Node 20 has global fetch. Test cases:
  - GET /api/health → 200, body.status === 'ok', service name, has timestamp.
  - GET /api/nope → 404, error.code === 'NOT_FOUND'.
  - Error handler: hard to trigger without a route that throws; add a test-only route? I don't want a test-only route in the app. Alternative: unit-test the errorHandler function directly by calling it with fake req/res objects. That's clean: build a fake res with status/json capture, call errorHandler(new Error('boom')), assert 500 + code INTERNAL_ERROR. And with err.status=404 & code NOT_FOUND assert pass-through. Also notFoundHandler with fake res.
  - env fail-fast: spawn `node -e` in a clean env without DATABASE_URL and expect exit code 1 and message. Using child_process.execFile in the test. That's a meaningful test of the fail-fast. But it spawns node — fine in CI. Include it: `node --input-type=module -e "import('./src/config/env.js')"` with env minus DATABASE_URL → expect non-zero exit. Use `node -e "import('...')"`... module resolution from cwd. Use `process.execPath` with `-e "await import('./src/config/env.js')"` — top-level await in -e is supported with --input-type=module? In -e, Node 20: dynamic import works: `node -e "import('./src/config/env.js').catch(e=>{console.error(e);process.exit(1)})"`. Hmm, top-level await in -e has been supported since Node 16? For -e, the code is treated as CommonJS unless --input-type=module; with --input-type=module, top-level await works (Node ≥ 14.8 or so with module input type... actually TLA in -e with input-type=module works in Node 14+? There were issues; safe bet: use a dynamic import with catch).

Let me write the env test:
```js
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
const execFileAsync = promisify(execFile);

test('env.js fails fast when DATABASE_URL is missing', async () => {
  const cleanEnv = { ...process.env };
  delete cleanEnv.DATABASE_URL;
  await assert.rejects(
    execFileAsync(process.execPath, ['--input-type=module', '-e', "await import('./src/config/env.js'); console.log('loaded')"], { cwd: new URL('..', import.meta.url), env: cleanEnv }),
    /Missing required environment variable: DATABASE_URL/
  );
});
```
cwd: the test file is in tests/, so `..` → backend/. import('./src/config/env.js') relative to cwd? Dynamic import inside -e resolves relative to cwd (with --eval, the module URL is relative to cwd: "eval" pseudo-url based on cwd). Yes, `import('./src/...')` from -e resolves relative to cwd. Good.

But note: with --input-type=module, TLA `await import(...)` — supported in Node 20 (TLA has been supported in --eval since v16? Let me think: top-level await in --eval works with --input-type=module from Node 14.8? There was a period when it was rejected... in Node ≥ 16 I'm fairly confident it works; Node 20 definitely). If DATABASE_URL is set (the test suite is run by the developer with .env? No — env.js reads process.env, not .env files; the test runner env won't have DATABASE_URL unless the shell has it). In the test I explicitly strip it, so it's deterministic.

- tests/health.test.js — HTTP-level tests:
```js
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import app from '../src/app.js';
import { prisma } from ... 
```
Wait — importing src/app.js imports routes → controllers → config/env.js → throws if DATABASE_URL missing! Because env.js loads at module level and throws. Tests will need DATABASE_URL set. Hmm. Options:
- In tests, set process.env.DATABASE_URL to a dummy before importing app (the test file sets env before import — but imports are hoisted! ESM imports run before the module body. Need dynamic import after setting env, or use `--test` with a global setup. Simplest: in the test file:
```js
process.env.DATABASE_URL ??= 'postgresql://test:test@localhost:5432/test';
const { default: app } = await import('../src/app.js');
```
TLA await import in the test file (test files are ESM) — works. But careful: setting env before a static import is not possible (hoisting). So use dynamic import after setting. Or set the env in package.json test script: `DATABASE_URL=... node --test`? Windows PowerShell doesn't support cross-platform env var syntax. Better: a test helper module `tests/helpers/test-env.js` that sets process.env.DATABASE_URL ??= ... imported first... but the import order across files — the app test imports the helper statically, then imports app statically; ESM hoisting: both imports execute in declaration order (imports are hoisted and evaluated in order of appearance). So:
```js
import '../helpers/ensure-test-env.js';
import app from '../src/app.js';
```
Both static; ensure-test-env.js sets process.env.DATABASE_URL ??= dummy. Evaluation order: ensure-test-env first (first import specifier), then app → env.js reads dummy URL → OK. PrismaClient construction with dummy URL — no connection attempt.

That's clean. helper:
```js
process.env.DATABASE_URL ??= 'postgresql://contractguard:contractguard@localhost:5432/contractguard_test';
```

And health HTTP test:
```js
import { test, before, after, beforeAll } from 'node:test';
```
Use before/after (node:test has before/after hooks that work at the file level). Start server on port 0 in before, close in after.

fetch is available globally (Node 18+).

Test cases:
1. health 200 + shape
2. unknown route 404 envelope
3. error handler unit test (direct function call, fake res)
4. notFound handler unit test
5. env fail-fast spawn test

All zero-dep.

