// Centralised environment configuration.
// Loaded once at startup; the process fails fast when a required variable is missing.

const REQUIRED_VARS = ['DATABASE_URL'];

function readRequired(name) {
  const value = process.env[name];
  if (value === undefined || value === '') {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

export function loadEnv() {
  for (const name of REQUIRED_VARS) {
    readRequired(name);
  }

  const portRaw = process.env.PORT;
  const port =
    portRaw === undefined || portRaw === '' ? 3000 : Number.parseInt(portRaw, 10);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`Invalid PORT: ${portRaw}`);
  }

  return Object.freeze({
    nodeEnv: process.env.NODE_ENV || 'development',
    port,
    databaseUrl: readRequired('DATABASE_URL'),
    webhookTargetUrl: process.env.WEBHOOK_TARGET_URL || 'http://localhost:9900',
  });
}

export const env = loadEnv();

// Reusable Prisma client (process-wide singleton).
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

/**
 * Verify database connectivity by executing a trivial query.
 * Throws Prisma's connection error when the database is unreachable.
 */
export async function verifyConnection() {
  await prisma.$queryRaw`SELECT 1`;
  return true;
}

export default prisma;

// Catch-all for requests that matched no route. Must be registered after the routes.
export function notFoundHandler(req, res) {
  res.status(404).json({
    error: {
      code: 'NOT_FOUND',
      message: `Cannot ${req.method} ${req.path}`,
    },
  });
}

// Centralised error handling. Emits the consistent JSON error envelope:
// { "error": { "code", "message", "details?" } }
import { env } from '../config/env.js';

export function errorHandler(err, req, res, next) {
  // next is unused; the 4-arg signature marks this as Express error middleware.
  const status = Number.isInteger(err.status) ? err.status : 500;
  const isServerError = status >= 500;
  const exposeMessage = !isServerError || env.nodeEnv !== 'production';

  if (isServerError) {
    console.error(`[error] ${req.method} ${req.path}:`, err);
  }

  const bodyParseFailed = err.type === 'entity.parse.failed';

  res.status(status).json({
    error: {
      code: err.code || (bodyParseFailed ? 'INVALID_JSON' : 'INTERNAL_ERROR'),
      message: bodyParseFailed
        ? 'Request body is not valid JSON'
        : exposeMessage
          ? err.message || 'Internal server error'
          : 'Internal server error',
      ...(Array.isArray(err.details) ? { details: err.details } : {}),
    },
  });
}

// Reports the API's own liveness. Intentionally independent of the database;
// connectivity is verified separately via verifyConnection() in database/prisma.js.
