async function stopPostgresReliably(pg) {
  const pid = pg.process?.pid;
  try {
    await Promise.race([
      pg.stop(),
      new Promise((resolve) => setTimeout(() => resolve('timeout'), 15000).unref()),
    ]);
  } catch { /* fall through to force-kill */ }
