generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

// Increment 1: Service Registry (Service).
// Increment 2: Specification Management (ApiVersion).
// The remaining models from the approved data model (ConsumerDependency,
// AnalysisRun, CompatibilityChange, ImpactFinding, PublishAttempt) are
// added in later increments, one per feature module.

model Service {
  id          String   @id @default(uuid())
  name        String   @unique
  owner       String
  description String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  apiVersions ApiVersion[]
}

enum SpecFormat {
  YAML
  JSON
}

enum VersionStatus {
  PROPOSED
  PUBLISHED
}

model ApiVersion {
  id        String @id @default(uuid())
  serviceId String
  // User-supplied identifier (e.g. "v1", "2026.11"). Not assumed to sort
  // lexicographically; "latest" is tracked by the publish flow, not by label.
  versionLabel    String
  // The exact content as uploaded, preserved for display/download/audit.
  originalContent String
  // Parsed and fully $ref-resolved document, stored as normalized JSON for
  // consistent comparison in the (later) diffing engine.
  parsedContent   Json
  format          SpecFormat
  // Detected OpenAPI version string, e.g. "3.0.3".
  openApiVersion  String
  status          VersionStatus @default(PROPOSED)
  createdAt       DateTime      @default(now())
  updatedAt       DateTime      @updatedAt

  service Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)

  @@unique([serviceId, versionLabel])
}

// Reusable OpenAPI specification validation.
//
// Pure module — no database access, no Express. Parses YAML or JSON content,
// validates the OpenAPI document structure with @apidevtools/swagger-parser
// (which also resolves internal $ref references), and returns structured
// errors. Used by the specs endpoints today and by the comparison engine
// later.
//
// Supported documents: OpenAPI 3.x (the parser validates 3.0.0–3.0.4 and
// 3.1.0–3.1.2). Swagger 2.0 documents are rejected explicitly.

import { load as loadYaml } from 'js-yaml';
import SwaggerParser from '@apidevtools/swagger-parser';

const MAX_CONTENT_LENGTH = 1_000_000; // 1 MB, mirrors the HTTP body limit

// Un-escape an AJV instancePath ("~1" -> "/", "~0" -> "~").
function unescapePointer(instancePath) {
  if (!instancePath) return '';
  return instancePath.replace(/~1/g, '/').replace(/~0/g, '~');
}

// First line only, bounded, so a huge payload cannot balloon an error message.
function firstLine(value, max = 300) {
  const line = String(value).split('\n', 1)[0];
  return line.length > max ? `${line.slice(0, max)}…` : line;
}

function makeError(code, message, path = undefined) {
  return path === undefined ? { code, message } : { code, message, path };
}

// Detect the format to parse with. An explicit `format` wins; then a
// `filename` extension; otherwise auto-detect (JSON first, since every valid
// JSON document is also valid YAML).
function detectFormat(content, { filename, format } = {}) {
  if (format === 'yaml') return 'yaml';
  if (format === 'json') return 'json';

  if (typeof filename === 'string') {
    const lower = filename.toLowerCase();
    if (lower.endsWith('.json')) return 'json';
    if (lower.endsWith('.yaml') || lower.endsWith('.yml')) return 'yaml';
  }

  return 'auto';
}

// Parse raw content into a JS value. Returns { ok: true, value, format } or
// { ok: false, errors } with a PARSE_ERROR.
function parseContent(content, mode) {
  if (mode === 'json') {
    try {
      return { ok: true, value: JSON.parse(content), format: 'json' };
    } catch (err) {
      return {
        ok: false,
        errors: [
          makeError('PARSE_ERROR', `Content is not valid JSON: ${firstLine(err.message)}`),
        ],
      };
    }
  }

  if (mode === 'yaml') {
    try {
      return { ok: true, value: loadYaml(content), format: 'yaml' };
    } catch (err) {
      // YAMLException messages already include the offending line/column and
      // a snippet, which is what callers want to see.
      return { ok: false, errors: [makeError('PARSE_ERROR', firstLine(err.message, 500))] };
    }
  }

  // auto: JSON is a subset of YAML, so a successful JSON.parse means the
  // content is JSON; otherwise treat it as YAML.
  try {
    return { ok: true, value: JSON.parse(content), format: 'json' };
  } catch {
    // fall through to YAML
  }
  try {
    return { ok: true, value: loadYaml(content), format: 'yaml' };
  } catch (err) {
    return {
      ok: false,
      errors: [makeError('PARSE_ERROR', firstLine(err.message, 500))],
    };
  }
}

// Validate the `openapi`/`swagger` version field before delegating to the
// parser, so the error messages are specific (the parser's own message is
// less useful for the common cases).
function checkVersion(doc) {
  if (typeof doc.openapi === 'number') {
    return {
      ok: false,
      error: makeError(
        'INVALID_DOCUMENT',
        `openapi version must be a quoted string (got a number; write openapi: "3.0.3" in YAML)`
      ),
    };
  }
  if (typeof doc.openapi === 'string') {
    if (!doc.openapi.startsWith('3.')) {
      return {
        ok: false,
        error: makeError(
          'UNSUPPORTED_VERSION',
          `Unsupported OpenAPI version "${doc.openapi}" — this registry supports OpenAPI 3.x`
        ),
      };
    }
    return { ok: true, version: doc.openapi };
  }
  if (typeof doc.swagger === 'string') {
    return {
      ok: false,
      error: makeError(
        'UNSUPPORTED_VERSION',
        `Swagger ${doc.swagger} documents are not supported — this registry accepts OpenAPI 3.x specifications`
      ),
    };
  }
  return {
    ok: false,
    error: makeError(
      'INVALID_DOCUMENT',
      "Document is not an OpenAPI specification: missing the 'openapi' version field"
    ),
  };
}

// Map a thrown swagger-parser error to structured validation errors.
function mapParserError(err) {
  // Unresolvable $ref (internal or external).
  if (err.code === 'EMISSINGPOINTER' || err.code === 'ERESOLVER') {
    const ref =
      err.targetRef ?? (String(err.message).match(/Missing \$ref pointer "([^"]+)"/)?.[1]);
    const external =
      ref && !ref.startsWith('#')
        ? ' (external file references are not supported; keep all $ref pointers inside the document)'
        : '';
    return [
      makeError(
        'UNRESOLVED_REFERENCE',
        `Unresolved $ref "${ref ?? 'unknown'}". ${err.message}${external}`,
        ref
      ),
    ];
  }

  // Schema validation failure: the parser aggregates AJV errors in .details.
  if (Array.isArray(err.details)) {
    return err.details.map((detail) =>
      makeError(
        'SCHEMA_VALIDATION',
        detail.message,
        unescapePointer(detail.instancePath)
      )
    );
  }

  // Unsupported/unknown OpenAPI version.
  if (/Unsupported OpenAPI version/.test(err.message)) {
    return [
      makeError(
        'UNSUPPORTED_VERSION',
        `Unsupported OpenAPI version — ${firstLine(err.message.replace(/^Swagger schema validation failed\.\s*/, ''))}`
      ),
    ];
  }

  return [makeError('SPEC_VALIDATION_ERROR', firstLine(err.message, 500))];
}

/**
 * Validate an OpenAPI specification.
 *
 * @param {string} content  Raw specification text (YAML or JSON).
 * @param {{ filename?: string, format?: 'yaml' | 'json' }} [options]
 *   filename — optional file name used as a format hint (.json/.yaml/.yml).
 *   format   — optional explicit format; wins over filename detection.
 * @returns {Promise<{
 *   ok: true,
 *   format: 'yaml' | 'json',
 *   openApiVersion: string,
 *   resolved: object,          // fully $ref-resolved document
 * } | {
 *   ok: false,
 *   format?: 'yaml' | 'json',
 *   openApiVersion?: string,
 *   errors: Array<{ code: string, message: string, path?: string }>,
 * }>}
 */
export async function validateSpecContent(content, options = {}) {
  if (typeof content !== 'string' || content.trim() === '') {
    return {
      ok: false,
      errors: [makeError('INVALID_CONTENT', 'Specification content is required (non-empty string)')],
    };
  }
  if (content.length > MAX_CONTENT_LENGTH) {
    return {
      ok: false,
      errors: [
        makeError(
          'INVALID_CONTENT',
          `Specification content is too large (${content.length} bytes, max ${MAX_CONTENT_LENGTH})`
        ),
      ],
    };
  }

  const mode = detectFormat(content, options);
  const parsed = parseContent(content, mode);
  if (!parsed.ok) return { ok: false, errors: parsed.errors };

  const doc = parsed.value;
  if (typeof doc !== 'object' || doc === null || Array.isArray(doc)) {
    return {
      ok: false,
      format: parsed.format,
      errors: [
        makeError(
          'INVALID_DOCUMENT',
          `OpenAPI document must be an object (mapping); got ${
            doc === null ? 'null' : Array.isArray(doc) ? 'an array' : typeof doc
          }`
        ),
      ],
    };
  }

  const version = checkVersion(doc);
  if (!version.ok) {
    return { ok: false, format: parsed.format, errors: [version.error] };
  }

  try {
    const resolved = await SwaggerParser.validate(doc);
    return {
      ok: true,
      format: parsed.format,
      openApiVersion: version.version,
      resolved,
    };
  } catch (err) {
    return {
      ok: false,
      format: parsed.format,
      openApiVersion: version.version,
      errors: mapParserError(err),
    };
  }
}

export default validateSpecContent;

// Input validation for the Specification Management endpoints.
// Pure functions: no I/O, no Prisma.

import { isValidUuid } from './service.validators.js';

const MAX_VERSION_LABEL_LENGTH = 100;
const MAX_FILENAME_LENGTH = 255;

// Validates an optional format hint. Returns the normalised format
// ('yaml' | 'json'), or an error message.
function checkFormatHint(body) {
  if (body.format === undefined) return { ok: true, format: undefined };
  if (typeof body.format !== 'string') {
    return { ok: false, message: 'format must be a string ("yaml" or "json")' };
  }
  const normalised = body.format.trim().toLowerCase();
  if (normalised !== 'yaml' && normalised !== 'json') {
    return { ok: false, message: 'format must be "yaml" or "json"' };
  }
  return { ok: true, format: normalised };
}

// Validates an optional filename hint.
function checkFilenameHint(body) {
  if (body.filename === undefined) return { ok: true, filename: undefined };
  if (typeof body.filename !== 'string') {
    return { ok: false, message: 'filename must be a string' };
  }
  const filename = body.filename.trim();
  if (filename.length > MAX_FILENAME_LENGTH) {
    return {
      ok: false,
      message: `filename must be at most ${MAX_FILENAME_LENGTH} characters`,
    };
  }
  return { ok: true, filename };
}

// Validates the POST /api/specs/validate body.
// Returns { ok: true, data } or { ok: false, errors: [{ field, message }] }.
export function validateSpecCheckBody(body) {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return {
      ok: false,
      errors: [{ field: 'body', message: 'Request body must be a JSON object' }],
    };
  }

  const errors = [];

  if (typeof body.content !== 'string' || body.content.trim() === '') {
    errors.push({ field: 'content', message: 'content is required and must be a non-empty string' });
  }

  const format = checkFormatHint(body);
  if (!format.ok) errors.push({ field: 'format', message: format.message });
  const filename = checkFilenameHint(body);
  if (!filename.ok) errors.push({ field: 'filename', message: filename.message });

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, data: { content: body.content, format: format.format, filename: filename.filename } };
}

// Validates the POST /api/specs/upload body.
// Returns { ok: true, data } or { ok: false, errors: [{ field, message }] }.
export function validateSpecUploadBody(body) {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return {
      ok: false,
      errors: [{ field: 'body', message: 'Request body must be a JSON object' }],
    };
  }

  const errors = [];

  if (typeof body.serviceId !== 'string' || !isValidUuid(body.serviceId)) {
    errors.push({ field: 'serviceId', message: 'serviceId is required and must be a valid UUID' });
  }

  if (typeof body.versionLabel !== 'string') {
    errors.push({ field: 'versionLabel', message: 'versionLabel is required and must be a string' });
  } else {
    const versionLabel = body.versionLabel.trim();
    if (versionLabel === '') {
      errors.push({ field: 'versionLabel', message: 'versionLabel must not be empty' });
    } else if (versionLabel.length > MAX_VERSION_LABEL_LENGTH) {
      errors.push({
        field: 'versionLabel',
        message: `versionLabel must be at most ${MAX_VERSION_LABEL_LENGTH} characters`,
      });
    }
  }

  if (typeof body.content !== 'string' || body.content.trim() === '') {
    errors.push({ field: 'content', message: 'content is required and must be a non-empty string' });
  }

  const format = checkFormatHint(body);
  if (!format.ok) errors.push({ field: 'format', message: format.message });
  const filename = checkFilenameHint(body);
  if (!filename.ok) errors.push({ field: 'filename', message: filename.message });

  if (errors.length > 0) return { ok: false, errors };
  return {
    ok: true,
    data: {
      serviceId: body.serviceId,
      versionLabel: body.versionLabel.trim(),
      content: body.content,
      format: format.format,
      filename: filename.filename,
    },
  };
}

// Specification Management business logic.
// All Prisma access for specs lives here; controllers never query the
// database directly. OpenAPI parsing/validation is delegated to the reusable
// spec-validator module.
import { Prisma } from '@prisma/client';
import prisma from '../database/prisma.js';
import { ApiError } from '../utils/api-error.js';
import { getService } from './service-registry.service.js';
import { validateSpecContent } from './spec-validator.js';

// Returns the version's PUBLISHED baseline, if one exists.
// Publishing is not implemented yet, so this is null today; the lookup is in
// place so the publish flow can set the baseline without schema changes.
async function findPublishedBaseline(serviceId) {
  const published = await prisma.apiVersion.findFirst({
    where: { serviceId, status: 'PUBLISHED' },
    orderBy: { createdAt: 'desc' },
  });
  return published ? published.id : null;
}

/**
 * Validate and persist a new specification version as PROPOSED.
 *
 * @returns {Promise<{
 *   version: object,          // the created ApiVersion row
 *   isInitialVersion: boolean,
 *   baselineVersionId: string | null,
 * }>}
 */
export async function uploadSpecVersion({ serviceId, versionLabel, content, filename, format }) {
  // 1. The service must exist.
  const service = await getService(serviceId); // 404 SERVICE_NOT_FOUND

  // 2. The specification must be valid OpenAPI (parse + structure + $refs).
  const result = await validateSpecContent(content, { filename, format });
  if (!result.ok) {
    throw new ApiError(400, 'INVALID_SPEC', 'Specification failed validation', result.errors);
  }

  // 3. The (serviceId, versionLabel) pair must be unique.
  const existing = await prisma.apiVersion.findUnique({
    where: { serviceId_versionLabel: { serviceId, versionLabel } },
  });
  if (existing) {
    throw new ApiError(
      409,
      'DUPLICATE_VERSION',
      `Service "${service.name}" already has a version labeled "${versionLabel}"`
    );
  }

  // 4. Baseline context: is this the service's first version, and is there a
  //    published baseline to compare against later? No comparison happens in
  //    this increment — these are reported, not acted on.
  const [versionCount, baselineVersionId] = await Promise.all([
    prisma.apiVersion.count({ where: { serviceId } }),
    findPublishedBaseline(serviceId),
  ]);

  try {
    const version = await prisma.apiVersion.create({
      data: {
        serviceId,
        versionLabel,
        // Original content preserved verbatim; resolved document stored
        // separately for the comparison engine.
        originalContent: content,
        parsedContent: result.resolved,
        format: result.format === 'yaml' ? 'YAML' : 'JSON',
        openApiVersion: result.openApiVersion,
        status: 'PROPOSED',
      },
    });
    return { version, isInitialVersion: versionCount === 0, baselineVersionId };
  } catch (err) {
    // Guard against a race between the check in step 3 and the insert.
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === 'P2002'
    ) {
      throw new ApiError(
        409,
        'DUPLICATE_VERSION',
        `Service "${service.name}" already has a version labeled "${versionLabel}"`
      );
    }
    throw err;
  }
}

// Returns the full ApiVersion row (metadata plus stored content).
export async function getSpecVersion(id) {
  const version = await prisma.apiVersion.findUnique({ where: { id } });
  if (!version) {
    throw new ApiError(
      404,
      'SPEC_VERSION_NOT_FOUND',
      `Specification version with id "${id}" was not found`
    );
  }
  return version;
}

// HTTP handling for Specification Management. Delegates business logic and
// database access to the service layer; spec parsing/validation to the
// reusable spec-validator module.
import { uploadSpecVersion, getSpecVersion } from '../services/spec.service.js';
import { validateSpecContent } from '../services/spec-validator.js';
import { validateSpecCheckBody, validateSpecUploadBody } from '../validators/spec.validators.js';
import { isValidUuid } from '../validators/service.validators.js';
import { ApiError } from '../utils/api-error.js';

// POST /api/specs/validate — checks a specification without persisting it.
// Returns 200 with { valid, format, openApiVersion, errors } whether or not
// the specification is valid: the validity verdict is the payload, not an
// HTTP error.
export async function validateSpec(req, res) {
  const result = validateSpecCheckBody(req.body);
  if (!result.ok) {
    throw new ApiError(400, 'VALIDATION_ERROR', 'Request body failed validation', result.errors);
  }

  const outcome = await validateSpecContent(result.data.content, {
    filename: result.data.filename,
    format: result.data.format,
  });

  res.json({
    success: true,
    data: {
      valid: outcome.ok,
      format: outcome.format ?? null,
      openApiVersion: outcome.openApiVersion ?? null,
      errors: outcome.ok ? [] : outcome.errors,
    },
  });
}

// POST /api/specs/upload — persists a new PROPOSED specification version.
export async function uploadSpec(req, res) {
  const result = validateSpecUploadBody(req.body);
  if (!result.ok) {
    throw new ApiError(400, 'VALIDATION_ERROR', 'Request body failed validation', result.errors);
  }

  const { version, isInitialVersion, baselineVersionId } = await uploadSpecVersion(result.data);

  res.status(201).json({
    success: true,
    data: {
      id: version.id,
      serviceId: version.serviceId,
      versionLabel: version.versionLabel,
      format: version.format,
      openApiVersion: version.openApiVersion,
      status: version.status,
      isInitialVersion,
      baselineVersionId,
      createdAt: version.createdAt,
      updatedAt: version.updatedAt,
    },
  });
}

// GET /api/specs/:id — metadata and stored content for one version.
export async function getSpecVersionById(req, res) {
  const { id } = req.params;
  if (!isValidUuid(id)) {
    throw new ApiError(400, 'INVALID_ID', 'id must be a valid UUID');
  }
  const version = await getSpecVersion(id);
  res.json({ success: true, data: version });
}

import { Router } from 'express';
import {
  validateSpec,
  uploadSpec,
  getSpecVersionById,
} from '../controllers/specs.controller.js';

const router = Router();

router.post('/validate', validateSpec);
router.post('/upload', uploadSpec);
router.get('/:id', getSpecVersionById);

export default router;

