// Throwaway smoke test against the live dev API on port 3000.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const base = 'http://127.0.0.1:3000';
const policySpec = readFileSync(fileURLToPath(new URL('../specs/policy-api/1-initial.yaml', import.meta.url)), 'utf8');
const claimsBroken = readFileSync(fileURLToPath(new URL('../specs/claims-api/2-channel-and-notes.yaml', import.meta.url)), 'utf8');

async function req(method, path, body) {
  const res = await fetch(base + path, {
    method,
    headers: body ? { 'content-type': 'application/json' } : undefined,
    body: body ? JSON.stringify(body) : undefined,
  });
  const text = await res.text();
  let json;
  try { json = JSON.parse(text); } catch { json = text; }
  console.log(`${method} ${path} -> ${res.status}`);
  return { status: res.status, json };
}

// 1. register a temp service
const svc = await req('POST', '/api/services', { name: 'smoke-api', owner: 'Smoke Test' });
console.log('  service:', JSON.stringify(svc.json.data ?? svc.json));
const serviceId = svc.json.data.id;

// 2. validate: good spec
const ok = await req('POST', '/api/specs/validate', { content: policySpec });
console.log('  valid:', JSON.stringify(ok.json.data));

// 3. validate: broken ref
const bad = await req('POST', '/api/specs/validate', { content: claimsBroken });
console.log('  valid:', JSON.stringify(bad.json.data));

// 4. upload first version
const up1 = await req('POST', '/api/specs/upload', { serviceId, versionLabel: 'v1', content: policySpec });
console.log('  upload v1:', JSON.stringify(up1.json.data ?? up1.json));
const v1id = up1.json.data?.id;

// 5. versions list
const list = await req('GET', `/api/services/${serviceId}/versions`);
console.log('  versions:', JSON.stringify(list.json.data));

// 6. detail
const det = await req('GET', `/api/specs/${v1id}`);
const d = det.json.data;
