// Semantic normalization of validated OpenAPI documents.
//
// Pure module — no database, no Express. Converts a *resolved* OpenAPI 3.x
// document (one with all internal $ref pointers already dereferenced, e.g.
// the parsedContent stored by spec management, or the output of
// SwaggerParser.parse/validate) into a deterministic internal representation
// that the comparison engine can diff without being affected by formatting,
// property order, $ref layout, or path parameter names.
//
// The normalized representation captures the contract-relevant surface:
// operations (method, path, parameters, request body, responses) and the
// shape of every request/response schema (types, nesting, arrays, enums,
// requiredness, formats, constraints).
//
// What is intentionally NOT part of the representation (documented
// limitations):
//   - Deprecated flags, x-* extensions, description/summary text,
//     security schemes, servers, tags.
//   - Schema composition (allOf/oneOf/anyOf/not), discriminators,
//     patternProperties, schema-valued additionalProperties, OpenAPI 3.1
//     union types: these are reported as UNSUPPORTED_CONSTRUCT, never
//     silently dropped.

const METHODS = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'];

const CONSTRAINT_KEYS = [
  'minimum', 'maximum', 'exclusiveMinimum', 'exclusiveMaximum',
  'minLength', 'maxLength', 'pattern',
  'minItems', 'maxItems', 'uniqueItems',
  'multipleOf', 'minProperties', 'maxProperties',
];

function escapePointerSegment(segment) {
  return String(segment).replace(/~/g, '~0').replace(/\//g, '~1');
}

function childPointer(pointer, segment) {
  return `${pointer}/${escapePointerSegment(segment)}`;
}

// /users/{id}/roles -> /users/{param_0}/roles. Parameter names are
// replaced by positional placeholders so that /users/{id} and
// /users/{userId} normalise to the same template, while static segments
// stay intact.
export function canonicalPath(path) {
  let position = 0;
  return String(path).replace(/\{[^}]*\}/g, () => `{param_${position += 1}}`);
}

// Stable order for array values that are compared as sets (required lists,
// enum values).
function stableSort(values) {
  return values.slice().sort((a, b) => {
    const ka = JSON.stringify(a);
    const kb = JSON.stringify(b);
    return ka < kb ? -1 : ka > kb ? 1 : 0;
  });
}
