function compareOperations(fromOp, toOp, changes) {
  const ctx = {
    method: fromOp.method,
    path: fromOp.path,  // baseline path; the endpoint is the same
  };

  if (fromOp.operationId !== toOp.operationId) {
    changes.push(makeChange('OPERATION_ID_CHANGED', { ...ctx, location: 'operation', before: { operationId: fromOp.operationId }, after: { operationId: toOp.operationId } }));
  }

  // Path parameters: pair by position in the path template (names may differ).
  const fromNames = pathParameterNames(fromOp.path);
  const toNames = pathParameterNames(toOp.path);
  const n = Math.max(fromNames.length, toNames.length);
  for (let i = 0; i < n; i += 1) {
    const fromName = fromNames[i] ?? null;
    const toName = toNames[i] ?? null;
    const fromParam = fromName !== null ? findParameter(fromOp, fromName, 'path') : null;
    const toParam = toName !== null ? findParameter(toOp, toName, 'path') : null;
    const display = toName ?? fromName ?? `param_${i}`;
    const paramCtx = { ...ctx, location: 'parameter', fieldPath: `parameters.${fromName ?? display}` };
    if (fromParam === null && toParam === null) continue;
    if (fromParam === null) {
      changes.push(makeChange('PARAMETER_ADDED', { ...paramCtx, before: null, after: toParam }));
      continue;
    }
    if (toParam === null) {
      changes.push(makeChange('PARAMETER_REMOVED', { ...paramCtx, before: fromParam, after: null }));
      continue;
    }
    compareParameterPair(fromParam, toParam, paramCtx, changes);
  }

  // Non-path parameters: match by (in, name) — the name is part of the contract.
  const fromOthers = fromOp.parameters.filter((p) => p.in !== 'path');
  const toOthers = toOp.parameters.filter((p) => p.in !== 'path');
  for (const key of sortedKeys(paramKeyMap(fromOthers), paramKeyMap(toOthers))) {
    const [inLocation, name] = key.split(':');
    const fromParam = fromOthers.find((p) => `${p.in}:${p.name}` === key) ?? null;
    const toParam = toOthers.find((p) => `${p.in}:${p.name}` === key) ?? null;
    const paramCtx = { ...ctx, location: 'parameter', fieldPath: `parameters.${name}` };
    if (!fromParam && toParam) changes.push(makeChange('PARAMETER_ADDED', { ...paramCtx, before: null, after: toParam }));
    else if (fromParam && !toParam) changes.push(makeChange('PARAMETER_REMOVED', { ...paramCtx, before: fromParam, after: null }));
    else compareParameterPair(fromParam, toParam, paramCtx, changes);
  }

  compareRequestBodies(fromOp.requestBody, toOp.requestBody, ctx, changes);
  compareResponses(fromOp.responses, toOp.responses, ctx, changes);
}

function compareParameterPair(fromParam, toParam, paramCtx, changes) {
