    changes.push(makeChange('PARAMETER_REQUIREDNESS_CHANGED', { ...paramCtx, before: { required: fromParam.required }, after: { required: toParam.required } }));
  }
  diffParameterSchema(fromParam.schema, toParam.schema, paramCtx, changes);
}
