export function compareSpecs(fromSpec, toSpec) {
  const changes = [];
  const fromIndex = indexByPath(fromSpec);
  const toIndex = indexByPath(toSpec);

  for (const canonicalPath of [...new Set([...fromIndex.keys(), ...toIndex.keys()])].sort()) {
    const fromEntry = fromIndex.get(canonicalPath);
    const toEntry = toIndex.get(canonicalPath);

    if (!fromEntry) {
      changes.push(makeChange('ENDPOINT_ADDED', { path: toEntry.originalPath, location: 'endpoint', method: null, before: null, after: { methods: [...toEntry.methods.keys()].sort(byMethodOrder) } }));
      continue;
