function normalizeSchema(schema, pointer, issues) {
  if (schema === null || schema === undefined) {
    return { type: 'any' };
  }
  if (typeof schema !== 'object' || Array.isArray(schema)) {
    issues.push({ code: 'INVALID_SCHEMA', message: `Schema must be an object at ${pointer}`, path: pointer });
    return { type: 'any' };
  }
  if ('$ref' in schema) {
    issues.push({
      code: 'UNRESOLVED_REFERENCE',
      message: `Found $ref "${schema.$ref}" at ${pointer}: the normalizer expects a fully $ref-resolved document`,
      path: pointer,
    });
    // Can't trust the shape of a schema behind an unresolved reference
    return { type: 'any' };
  }

  for (const construct of ['allOf', 'oneOf', 'anyOf', 'not', 'discriminator', 'patternProperties']) {
    if (construct in schema) {
      issues.push({
        code: 'UNSUPPORTED_CONSTRUCT',
        message: `Schema construct "${construct}" at ${pointer} is not supported by the normalizer`,
        path: pointer,
      });
    }
  }
  if (schema.additionalProperties !== undefined && typeof schema.additionalProperties === 'object' && schema.additionalProperties !== null) {
    issues.push({ code: 'UNSUPPORTED_CONSTRUCT', message: `Schema-valued additionalProperties at ${pointer} is not supported`, path: pointer });
  }

  let type;
  if (typeof schema.type === 'string') {
    type = schema.type;
  } else if (Array.isArray(schema.type)) {
    issues.push({ code: 'UNSUPPORTED_CONSTRUCT', message: `OpenAPI 3.1 union type ${JSON.stringify(schema.type)} at ${pointer} is not supported`, path: pointer });
    type = 'any';
  } else if (schema.type !== undefined) {
    issues.push({ code: 'INVALID_SCHEMA', message: `Schema "type" must be a string at ${pointer}`, path: pointer });
    type = 'any';
  } else {
    type = 'any';
  }

  const descriptor = { type };
  if (typeof schema.format === 'string') descriptor.format = schema.format;
  if (schema.nullable === true) descriptor.nullable = true;
  if (Array.isArray(schema.enum)) descriptor.enum = stableSort(schema.enum);

  for (const key of CONSTRAINT_KEYS) {
    if (key in schema) descriptor[key] = schema[key];
  }
  if (typeof schema.additionalProperties === 'boolean') descriptor.additionalProperties = schema.additionalProperties;

  const isObject = type === 'object' || (schema.properties !== undefined && typeof schema.properties === 'object');
  if (isObject) {
    descriptor.required = stableSort(Array.isArray(schema.required) ? schema.required : []);
    descriptor.properties = {};
    const properties = schema.properties && typeof schema.properties === 'object' ? schema.properties : {};
    for (const name of Object.keys(properties)) {
      descriptor.properties[name] = normalizeSchema(properties[name], childPointer(pointer, name), issues);
    }
  }

  const isArray = type === 'array' || schema.items !== undefined;
  if (isArray) {
    descriptor.items = normalizeSchema(schema.items, childPointer(pointer, 'items'), issues);
  }

  return descriptor;
}
