      return `Field "${leafOf(change.fieldPath)}" changed type from ${schemaTypePhrase(change.before)} to ${schemaTypePhrase(change.after)} in ${locationPhrase(change.location)} of ${where}.`;
    case 'FIELD_REQUIREDNESS_CHANGED':
      return `Field "${leafOf(change.fieldPath)}" changed from ${change.before.required ? 'required' : 'optional'} to ${change.after.required ? 'required' : 'optional'} in ${locationPhrase(change.location)} of ${where}.`;
    case 'ENUM_CHANGED':
      return `Field "${leafOf(change.fieldPath)}" changed enum values from ${enumPhrase(change.before.enum)} to ${enumPhrase(change.after.enum)} in ${locationPhrase(change.location)} of ${where}.`;
    case 'NULLABLE_CHANGED':
      return `Field "${leafOf(change.fieldPath)}" changed from ${change.before.nullable ? 'nullable' : 'non-nullable'} to ${change.after.nullable ? 'nullable' : 'non-nullable'} in ${locationPhrase(change.location)} of ${where}.`;
    case 'CONSTRAINT_CHANGED': {
      const key = Object.keys(change.before)[0];
      return `Field "${leafOf(change.fieldPath)}" constraint "${key}" changed from ${JSON.stringify(change.before[key])} to ${JSON.stringify(change.after[key])} in ${locationPhrase(change.location)} of ${where}.`;
    }
    default:
      return `${change.changeType} on ${where ?? 'the specification'}.`;
  }
}
