      if (removed.length > 0) {
        return breaking(`Request enum field "${field}" on ${where} removed value(s) ${valuesPhrase(removed)}${added.length > 0 ? ` and added ${valuesPhrase(added)}` : ''}. Clients that send the removed values will be rejected.`);
      }
      return nonBreaking(`Request enum field "${field}" on ${where} added value(s) ${valuesPhrase(added)} without removing accepted values. Previously accepted requests are still accepted.`);
    }
    case 'NULLABLE_CHANGED':
      return unknown(`Field "${field}" on ${where} changed from ${change.before.nullable ? 'nullable' : 'non-nullable'} to ${change.after.nullable ? 'nullable' : 'non-nullable'}. The initial rule set defines no rule for nullability changes; manual review is recommended.`);
    case 'CONSTRAINT_CHANGED': {
      const key = Object.keys(change.before ?? {})[0];
      return unknown(`Field "${field}" on ${where} changed constraint "${key}" from ${JSON.stringify(change.before?.[key])} to ${JSON.stringify(change.after?.[key])}. The initial rule set defines no rule for constraint changes; manual review is recommended.`);
    }
    default:
      return unknown(`Change type ${changeType} on ${where} has no rule in the initial rule set; manual review is required.`);
  }
}
