  ['claims 3 -> 4 (202 + requiredness)', 'claims-api/3-channel-and-notes-fixed.yaml', 'claims-api/4-approval-later.yaml'],
];

for (const [label, fromPath, toPath] of pairs) {
  const [fromResult, toResult] = await Promise.all([norm(fromPath), norm(toPath)]);
  if (!fromResult.ok || !toResult.ok) {
    console.log(label, '=> NORMALIZATION FAILED', fromResult.errors, toResult.errors);
    continue;
  }
  const changes = compareSpecs(fromResult.spec, toResult.spec);
  console.log(`\n=== ${label}: ${changes.length} changes ===`);
  for (const c of changes) {
    console.log(
      `  ${c.changeType} ${c.method ?? '-'} ${c.path ?? '-'} ${c.fieldPath ?? ''} :: ${c.description}`
    );
    if (c.before !== null) console.log(`    before: ${JSON.stringify(c.before)}`);
    if (c.after !== null) console.log(`    after:  ${JSON.stringify(c.after)}`);
  }
}

