120: // The response status a change refers to (from the fieldPath or location).
121: function statusOf(change) {
122:   if (typeof change.fieldPath === 'string' && change.fieldPath.startsWith('response.')) {
123:     return change.fieldPath.slice('response.'.length).split(/[.[\]]/)[0];
124:   }
125:   if (isResponseLocation(change.location)) {
126:     return change.location.slice('response.'.length);
127:   }
128:   return 'unknown';
129: }
130: 
131: function typePhrase(descriptor) {
132:   if (!descriptor || typeof descriptor !== 'object') return 'unknown';
133:   const type = descriptor.type ?? 'any';
134:   return descriptor.format ? `${type} (${descriptor.format})` : type;
135: }
136: 
137: // ---------------------------------------------------------------------------
138: // Classification
139: // ---------------------------------------------------------------------------
140: 
141: /**
142:  * Classify one structural change.
143:  *
144:  * @param {object} change a change produced by spec-comparator
145:  * @returns {{ compatibility: string, explanation: string }}
146:  */
147: export function classifyChange(change) {
148:   const { changeType } = change;
149:   const where = wherePhrase(change);
150:   const field = change.fieldPath ? fieldLeaf(change.fieldPath) : '';
151:   const inResponse = isResponseLocation(change.location);
152: 
153:   switch (changeType) {
154:     // ------------------------------------------------------------------
155:     // Operations
156:     // ------------------------------------------------------------------
157:     case 'ENDPOINT_REMOVED':
158:       return breaking(
159:         `Endpoint ${change.path} (methods: ${change.before.methods.join(', ')}) was removed. Any existing client that calls this endpoint will no longer reach it.`
160:       );
161:     case 'METHOD_REMOVED':
162:       return breaking(
163:         `${change.method} ${change.path} was removed. Existing clients that call this operation will receive 404/405 responses.`
164:       );
165:     case 'ENDPOINT_ADDED':
166:       return nonBreaking(
167:         `Endpoint ${change.path} (methods: ${change.after.methods.join(', ')}) was added. New surface area cannot affect existing clients.`
168:       );
169:     case 'METHOD_ADDED':
170:       return nonBreaking(
171:         `${change.method} ${change.path} was added. New surface area cannot affect existing clients.`
172:       );
173:     case 'OPERATION_ID_CHANGED':
174:       return unknown(
175:         `operationId changed from "${change.before.operationId}" to "${change.after.operationId}" on ${where}. The initial rule set defines no rule for operationId changes; generated clients may depend on it, so manual review is recommended.`
176:       );
177: 
178:     // ------------------------------------------------------------------
179:     // Request parameters
180:     // ------------------------------------------------------------------
181:     case 'PARAMETER_REMOVED':
182:       return breaking(
183:         `Parameter "${change.before.name}" (${change.before.in}) was removed from ${where}. Clients that send this parameter may be rejected or have it ignored.`
184:       );
185:     case 'PARAMETER_ADDED':
186:       return change.after.required
187:         ? breaking(
188:             `Required parameter "${change.after.name}" (${change.after.in}) was added to ${where}. Existing clients that do not send it will be rejected.`
189:           )
190:         : nonBreaking(
191:             `Optional parameter "${change.after.name}" (${change.after.in}) was added to ${where}. Clients that do not send it are unaffected.`
192:           );
193:     case 'PARAMETER_REQUIREDNESS_CHANGED':
194:       return change.after.required
195:         ? breaking(
196:             `Parameter "${field}" on ${where} became required. Existing clients that omit it will be rejected.`
197:           )
198:         : nonBreaking(
199:             `Parameter "${field}" on ${where} became optional. Clients that do send it are unaffected.`
200:           );
201:     case 'PARAMETER_TYPE_CHANGED':
202:       return breaking(
203:         `Parameter "${field}" on ${where} changed type from ${typePhrase(change.before)} to ${typePhrase(change.after)}. Clients sending the previous type may no longer be accepted.`
204:       );
205:     case 'PARAMETER_ENUM_CHANGED': {
206:       const { removed, added } = enumDiff(change.before.enum, change.after.enum);
207:       if (removed.length > 0) {
208:         return breaking(
209:           `Request enum value(s) ${valuesPhrase(removed)} for parameter "${field}" on ${where} were removed. Clients that send those values will be rejected.`
210:         );
211:       }
212:       return nonBreaking(
213:         `Request enum value(s) ${valuesPhrase(added)} for parameter "${field}" on ${where} were added. Values accepted before are still accepted.`
214:       );
215:     }
216: 
217:     // ------------------------------------------------------------------
218:     // Request body
219:     // ------------------------------------------------------------------
220:     case 'REQUEST_BODY_REMOVED':
221:       return breaking(
222:         `The request body on ${where} was removed. Clients that send a body may be rejected or have it ignored.`
223:       );
224:     case 'REQUEST_BODY_REQUIREDNESS_CHANGED':
225:       return change.after.required
226:         ? breaking(
227:             `The request body on ${where} became required. Clients that call it without a body will be rejected.`
228:           )
229:         : nonBreaking(
230:             `The request body on ${where} became optional. Clients that do send a body are unaffected.`
231:           );
232:     case 'REQUEST_BODY_ADDED':
233:       return unknown(
234:         `A request body was added to ${where}. The initial rule set defines no rule for adding a request body to an operation that had none; existing clients may not send a body, so manual review is recommended.`
235:       );
236:     case 'REQUEST_CONTENT_TYPE_ADDED':
237:       return unknown(
238:         `Content type "${change.after.contentType}" was added to the request body of ${where}. The initial rule set defines no rule for request content type changes; manual review is recommended.`
239:       );
240:     case 'REQUEST_CONTENT_TYPE_REMOVED':
241:       return unknown(
242:         `Content type "${change.before.contentType}" was removed from the request body of ${where}. The initial rule set defines no rule for request content type changes; manual review is recommended.`
243:       );
244: 
245:     // ------------------------------------------------------------------
246:     // Response status codes and content types
247:     // ------------------------------------------------------------------
248:     case 'RESPONSE_STATUS_ADDED':
249:       return nonBreaking(
250:         `Response status ${statusOf(change)} was added to ${where}. Clients that handle the statuses they already know are unaffected.`
251:       );
252:     case 'RESPONSE_STATUS_REMOVED':
253:       return unknown(
254:         `Response status ${statusOf(change)} was removed from ${where}. The initial rule set defaults removed response status codes to UNKNOWN; clients that handle or rely on this status may be affected, so manual review is recommended.`
255:       );
256:     case 'RESPONSE_CONTENT_TYPE_ADDED':
257:       return unknown(
258:         `Content type "${change.after.contentType}" was added to response ${statusOf(change)} of ${where}. The initial rule set defaults added response content types to UNKNOWN; manual review is recommended.`
259:       );
260:     case 'RESPONSE_CONTENT_TYPE_REMOVED':
261:       return unknown(
262:         `Content type "${change.before.contentType}" was removed from response ${statusOf(change)} of ${where}. The initial rule set defaults removed response content types to UNKNOWN; manual review is recommended.`
263:       );
264: 
265:     // ------------------------------------------------------------------
266:     // Schema fields (request and response)
267:     // ------------------------------------------------------------------
268:     case 'FIELD_ADDED': {
269:       const required = change.after?.required === true;
270:       if (inResponse) {
271:         return required
272:           ? unknown(
273:               `Required response field "${field}" was added to ${where}. The initial rule set classifies added required response fields as UNKNOWN: the schema alone does not establish whether existing consumers can handle a new required response member.`
274:             )
275:           : nonBreaking(
276:               `Optional response field "${field}" was added to ${where}. Consumers that ignore unknown fields are unaffected.`
277:             );
278:       }
279:       return required
280:         ? breaking(
281:             `Required request field "${field}" was added to ${where}. Existing clients that do not send it will be rejected.`
282:           )
283:         : nonBreaking(
284:             `Optional request field "${field}" was added to ${where}. Clients that do not send it are unaffected.`
285:           );
286:     }
287:     case 'FIELD_REMOVED':
288:       return breaking(
289:         inResponse
290:           ? `Response field "${field}" was removed from ${where}. Consumers that read this field will no longer receive it.`
291:           : `Request field "${field}" was removed from ${where}. Clients that send this field may be rejected or have it ignored.`
292:       );
293:     case 'FIELD_TYPE_CHANGED':
294:       return breaking(
295:         `Field "${field}" on ${where} changed type from ${typePhrase(change.before)} to ${typePhrase(change.after)}. Clients that (de)serialize the previous type will fail.`
296:       );
297:     case 'FIELD_REQUIREDNESS_CHANGED': {
298:       const becameRequired = change.after.required === true;
299:       if (inResponse) {
300:         return unknown(
301:           `Response field "${field}" on ${where} changed from ${change.before.required ? 'required' : 'optional'} to ${becameRequired ? 'required' : 'optional'}. The initial rule set defines no rule for response field requiredness changes; consumers that read this field ${becameRequired ? 'will now always receive it' : 'may now receive undefined'}, so manual review is recommended.`
302:         );
303:       }
304:       return becameRequired
305:         ? breaking(
306:             `Request field "${field}" on ${where} became required. Existing clients that omit it will be rejected.`
307:           )
308:         : nonBreaking(
309:             `Request field "${field}" on ${where} became optional. Clients that do send it are unaffected.`
310:           );
311:     }
312:     case 'ENUM_CHANGED': {
313:       const { removed, added } = enumDiff(change.before.enum, change.after.enum);
314:       if (inResponse) {
315:         const parts = [];
316:         if (removed.length > 0) parts.push(`value(s) ${valuesPhrase(removed)} removed`);
317:         if (added.length > 0) parts.push(`value(s) ${valuesPhrase(added)} added`);
318:         return unknown(
319:           `Response enum field "${field}" on ${where} changed (${parts.join('; ') || 'enum changed'}). The initial rule set defaults response enum changes to UNKNOWN; consumers that branch on these values may need updates, so manual review is recommended.`
320:         );
321:       }
322:       if (removed.length > 0) {
323:         return breaking(
324:           `Request enum field "${field}" on ${where} removed value(s) ${valuesPhrase(removed)}${
325:             added.length > 0 ? ` and added ${valuesPhrase(added)}` : ''
326:           }. Clients that send the removed values will be rejected.`
327:         );
328:       }
329:       return nonBreaking(
330:         `Request enum field "${field}" on ${where} added value(s) ${valuesPhrase(
331:           added
332:         )} without removing accepted values. Previously accepted requests are still accepted.`
333:       );
334:     }
335:     case 'NULLABLE_CHANGED':
336:       return unknown(
337:         `Field "${field}" on ${where} changed from ${change.before.nullable ? 'nullable' : 'non-nullable'} to ${change.after.nullable ? 'nullable' : 'non-nullable'}. The initial rule set defines no rule for nullability changes; manual review is recommended.`
338:       );
339:     case 'CONSTRAINT_CHANGED': {
340:       const key = Object.keys(change.before ?? {})[0];
341:       return unknown(
342:         `Field "${field}" on ${where} changed constraint "${key}" from ${JSON.stringify(
343:           change.before?.[key]
344:         )} to ${JSON.stringify(change.after?.[key])}. The initial rule set defines no rule for constraint changes; manual review is recommended.`
345:       );
346:     }
347:     default:
348:       return unknown(
349:         `Change type ${changeType} on ${where} has no rule in the initial rule set; manual review is required.`
350:       );
351:   }
352: }
353: 
354: // ---------------------------------------------------------------------------
355: // Whole change set
356: // ---------------------------------------------------------------------------
357: 
358: /**
359:  * Classify every change in a comparator output and summarise the result.
360:  *
361:  * @param {object[]} changes  output of spec-comparator
362:  * @returns {{
363:  *   changes: Array<object & { compatibility: string, explanation: string }>,
364:  *   summary: { total: number, breaking: number, nonBreaking: number, unknown: number },
365:  *   overallVerdict: string,
366:  * }}
367:  */
368: export function classifyChanges(changes) {
369:   const classified = changes.map((change) => {
370:     const { compatibility, explanation } = classifyChange(change);
371:     return { ...change, compatibility, explanation };
372:   });
373: 
374:   const summary = {
375:     total: classified.length,
376:     breaking: 0,
377:     nonBreaking: 0,
378:     unknown: 0,
379:   };
380:   for (const change of classified) {
381:     if (change.compatibility === COMPATIBILITY.BREAKING) summary.breaking += 1;
382:     else if (change.compatibility === COMPATIBILITY.NON_BREAKING) summary.nonBreaking += 1;
383:     else summary.unknown += 1;
384:   }
385: 
386:   const overallVerdict =
387:     summary.total === 0
388:       ? OVERALL_VERDICTS.NO_CHANGES
389:       : summary.breaking > 0
390:         ? OVERALL_VERDICTS.BREAKING
391:         : summary.unknown > 0
392:           ? OVERALL_VERDICTS.UNKNOWN
393:           : OVERALL_VERDICTS.NON_BREAKING;
394: 
395:   return { changes: classified, summary, overallVerdict };
396: }
397: 
398: export default classifyChanges;

input.content:
// Unit tests for the compatibility classification engine (pure module — no
// database, no HTTP server, no LLM). Exercises every row of the initial rule
// table, both directions of each conditional rule, and the UNKNOWN fallback
// for change types without an explicit rule.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  classifyChange,
  classifyChanges,
  COMPATIBILITY,
  OVERALL_VERDICTS,
} from '../src/services/compatibility-classifier.js';

function change(overrides = {}) {
  return {
    changeType: 'FIELD_REMOVED',
    method: 'GET',
    path: '/things',
    before: null,
    after: null,
    ...overrides,
  };
}

function requestField(changeType, { required = false } = {}) {
  return change({
    changeType,
    method: 'POST',
    path: '/things',
    location: 'request',
    fieldPath: 'request.nested.field',
    before: changeType === 'FIELD_ADDED' ? null : { required, type: 'string' },
    after: changeType === 'FIELD_REMOVED' ? null : { required, type: 'string' },
  });
}

function responseField(changeType, { required = false } = {}) {
  return change({
    changeType,
    location: 'response.200',
    fieldPath: 'response.200.field',
    before: changeType === 'FIELD_ADDED' ? null : { required, type: 'string' },
    after: changeType === 'FIELD_REMOVED' ? null : { required, type: 'string' },
  });
}

// ---------------------------------------------------------------------------
// Operations
// ---------------------------------------------------------------------------

test('removed endpoint is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'ENDPOINT_REMOVED',
      method: null,
      path: '/policies',
      location: 'endpoint',
      before: { methods: ['GET', 'POST'] },
      after: null,
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /\/policies/);
});

test('added endpoint is NON_BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'ENDPOINT_ADDED',
      method: null,
      path: '/policies/search',
      location: 'endpoint',
      before: null,
      after: { methods: ['GET'] },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
  assert.match(result.explanation, /\/policies\/search/);
});

test('removed method is BREAKING', () => {
  const result = classifyChange(
    change({ changeType: 'METHOD_REMOVED', method: 'DELETE', location: 'method' })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /DELETE \/things/);
});

test('added method is NON_BREAKING', () => {
  const result = classifyChange(
    change({ changeType: 'METHOD_ADDED', method: 'PUT', location: 'method' })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

test('operationId change is UNKNOWN (no rule defined)', () => {
  const result = classifyChange(
    change({
      changeType: 'OPERATION_ID_CHANGED',
      location: 'operation',
      before: { operationId: 'old' },
      after: { operationId: 'new' },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.UNKNOWN);
  assert.match(result.explanation, /old/);
  assert.match(result.explanation, /new/);
});

// ---------------------------------------------------------------------------
// Request parameters
// ---------------------------------------------------------------------------

test('removed parameter is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_REMOVED',
      location: 'parameter',
      fieldPath: 'parameters.limit',
      before: { name: 'limit', in: 'query', required: false, schema: { type: 'integer' } },
      after: null,
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /limit/);
});

test('added required parameter is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_ADDED',
      location: 'parameter',
      fieldPath: 'parameters.region',
      before: null,
      after: { name: 'region', in: 'query', required: true, schema: { type: 'string' } },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /region/);
});

test('added optional parameter is NON_BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_ADDED',
      location: 'parameter',
      fieldPath: 'parameters.verbose',
      before: null,
      after: { name: 'verbose', in: 'query', required: false, schema: { type: 'boolean' } },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

test('parameter optional -> required is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_REQUIREDNESS_CHANGED',
      location: 'parameter',
      fieldPath: 'parameters.limit',
      before: { required: false },
      after: { required: true },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
});

test('parameter required -> optional is NON_BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_REQUIREDNESS_CHANGED',
      location: 'parameter',
      fieldPath: 'parameters.limit',
      before: { required: true },
      after: { required: false },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

test('parameter type change is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_TYPE_CHANGED',
      location: 'parameter',
      fieldPath: 'parameters.limit',
      before: { type: 'string' },
      after: { type: 'integer' },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /string/);
  assert.match(result.explanation, /integer/);
});

test('parameter enum value removed is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_ENUM_CHANGED',
      location: 'parameter',
      fieldPath: 'parameters.status',
      before: { enum: ['DRAFT', 'FINAL'] },
      after: { enum: ['FINAL'] },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /DRAFT/);
});

test('parameter enum value added only is NON_BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'PARAMETER_ENUM_CHANGED',
      location: 'parameter',
      fieldPath: 'parameters.status',
      before: { enum: ['DRAFT', 'FINAL'] },
      after: { enum: ['DRAFT', 'EXPIRED', 'FINAL'] },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

// ---------------------------------------------------------------------------
// Request body
// ---------------------------------------------------------------------------

test('removed request body is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'REQUEST_BODY_REMOVED',
      method: 'POST',
      location: 'requestBody',
      before: { required: true, contentTypes: ['application/json'] },
      after: null,
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
});

test('request body optional -> required is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'REQUEST_BODY_REQUIREDNESS_CHANGED',
      method: 'POST',
      location: 'requestBody',
      before: { required: false },
      after: { required: true },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
});

test('request body required -> optional is NON_BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'REQUEST_BODY_REQUIREDNESS_CHANGED',
      method: 'POST',
      location: 'requestBody',
      before: { required: true },
      after: { required: false },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

test('added request body is UNKNOWN (no rule defined)', () => {
  const result = classifyChange(
    change({
      changeType: 'REQUEST_BODY_ADDED',
      method: 'POST',
      location: 'requestBody',
      before: null,
      after: { required: false, contentTypes: ['application/json'] },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.UNKNOWN);
});

test('request content type added/removed is UNKNOWN (no rule defined)', () => {
  const added = classifyChange(
    change({
      changeType: 'REQUEST_CONTENT_TYPE_ADDED',
      method: 'POST',
      location: 'request',
      fieldPath: 'request[text/plain]',
      before: null,
      after: { contentType: 'text/plain' },
    })
  );
  assert.equal(added.compatibility, COMPATIBILITY.UNKNOWN);

  const removed = classifyChange(
    change({
      changeType: 'REQUEST_CONTENT_TYPE_REMOVED',
      method: 'POST',
      location: 'request',
      fieldPath: 'request[text/plain]',
      before: { contentType: 'text/plain' },
      after: null,
    })
  );
  assert.equal(removed.compatibility, COMPATIBILITY.UNKNOWN);
});

// ---------------------------------------------------------------------------
// Request fields
// ---------------------------------------------------------------------------

test('added optional request field is NON_BREAKING', () => {
  const result = classifyChange(requestField('FIELD_ADDED', { required: false }));
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
  assert.match(result.explanation, /field/);
});

test('added required request field is BREAKING', () => {
  const result = classifyChange(requestField('FIELD_ADDED', { required: true }));
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
});

test('removed request field is BREAKING', () => {
  const result = classifyChange(requestField('FIELD_REMOVED'));
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
});

test('request field type change is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'FIELD_TYPE_CHANGED',
      method: 'POST',
      location: 'request',
      fieldPath: 'request.amount',
      before: { type: 'string' },
      after: { type: 'number' },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
});

test('request field optional -> required is BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'FIELD_REQUIREDNESS_CHANGED',
      method: 'POST',
      location: 'request',
      fieldPath: 'request.notes',
      before: { required: false },
      after: { required: true },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
});

test('request field required -> optional is NON_BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'FIELD_REQUIREDNESS_CHANGED',
      method: 'POST',
      location: 'request',
      fieldPath: 'request.notes',
      before: { required: true },
      after: { required: false },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

test('request enum value removed is BREAKING (even when others are added)', () => {
  const result = classifyChange(
    change({
      changeType: 'ENUM_CHANGED',
      method: 'POST',
      location: 'request',
      fieldPath: 'request.type',
      before: { enum: ['ADDRESS', 'NOMINEE', 'VEHICLE'] },
      after: { enum: ['ADDRESS', 'NOMINEE'] },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /VEHICLE/);
});

test('request enum value added only is NON_BREAKING', () => {
  const result = classifyChange(
    change({
      changeType: 'ENUM_CHANGED',
      method: 'POST',
      location: 'request',
      fieldPath: 'request.channel',
      before: { enum: ['APP', 'WEB'] },
      after: { enum: ['APP', 'PARTNER', 'WEB'] },
    })
  );
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

// ---------------------------------------------------------------------------
// Response fields
// ---------------------------------------------------------------------------

test('removed response field is BREAKING', () => {
  const result = classifyChange(responseField('FIELD_REMOVED'));
  assert.equal(result.compatibility, COMPATIBILITY.BREAKING);
  assert.match(result.explanation, /Response field/);
});

test('added optional response field is NON_BREAKING', () => {
  const result = classifyChange(responseField('FIELD_ADDED', { required: false }));
  assert.equal(result.compatibility, COMPATIBILITY.NON_BREAKING);
});

test('added required response field is UNKNOWN', () => {
