  assert.equal(removedAmount.length, 2);
  for (const change of removedAmount) assert.equal(change.compatibility, 'BREAKING');

  const addedValue = body.data.changes.filter((c) => c.changeType === 'FIELD_ADDED');
  assert.equal(addedValue.length, 2);
  for (const change of addedValue) assert.equal(change.compatibility, 'UNKNOWN');
