1: // Compatibility Classification — deterministic, rule-based engine.
2: //
3: // Pure module — no database, no Express, no LLM. Takes the structural change
4: // list produced by spec-comparator and classifies each change as
5: // BREAKING / NON_BREAKING / UNKNOWN.
6: //
7: // The classifier itself contains no policy: it walks the ordered rule list
8: // in compatibility-rules (the initial, product-owner-proposed rule set) and
9: // uses the first applicable rule. A change that matches no rule is
10: // classified UNKNOWN with ruleId "NO_RULE" — never silently NON_BREAKING.
11: // The same input always produces the same output.
12: //
13: // Each classified change preserves the original comparator fields and adds:
14: //   classification  BREAKING | NON_BREAKING | UNKNOWN
15: //   ruleId          machine-readable identifier of the rule that matched
16: //   reason          plain-language, change-specific explanation
17: //
18: // All rules are deterministic, so no separate confidence value is emitted:
19: // every rule that matches is the rule that applies, and UNKNOWN results
20: // always carry a reason that names the gap and recommends manual review.
21: 
22: import { RULES, COMPATIBILITY, wherePhrase } from './compatibility-rules.js';
23: 
24: /**
25:  * Classify one structural change.
26:  *
27:  * @param {object} change a change produced by spec-comparator
28:  * @returns {{ classification: string, ruleId: string, reason: string }}
29:  */
30: export function classifyChange(change) {
31:   for (const rule of RULES) {
32:     if (rule.applies(change)) {
33:       return {
34:         classification: rule.classification,
35:         ruleId: rule.ruleId,
36:         reason: rule.reason(change),
37:       };
38:     }
39:   }
40: 
41:   // No rule in the initial rule set covers this change type. The system
42:   // cannot determine compatibility with confidence, so the result is
43:   // UNKNOWN — never NON_BREAKING — and the reason says exactly why.
44:   return {
45:     classification: COMPATIBILITY.UNKNOWN,
46:     ruleId: 'NO_RULE',
47:     reason:
48:       `Change type ${change.changeType} on ${wherePhrase(change)} has no rule in the initial rule set. ` +
49:       'The system cannot determine compatibility with confidence, so the change is ' +
50:       'classified UNKNOWN; manual review is required.',
51:   };
52: }
53: 
54: /**
55:  * Classify every change in a comparator output and count the results.
56:  *
57:  * @param {object[]} changes  output of spec-comparator
58:  * @returns {{
59:  *   changes: Array<object & { classification: string, ruleId: string, reason: string }>,
60:  *   counts: { total: number, breaking: number, nonBreaking: number, unknown: number },
61:  * }}
62:  */
63: export function classifyChanges(changes) {
64:   const classified = changes.map((change) => ({
65:     ...change,
66:     ...classifyChange(change),
67:   }));
68: 
69:   const counts = { total: classified.length, breaking: 0, nonBreaking: 0, unknown: 0 };
70:   for (const change of classified) {
71:     if (change.classification === COMPATIBILITY.BREAKING) counts.breaking += 1;
72:     else if (change.classification === COMPATIBILITY.NON_BREAKING) counts.nonBreaking += 1;
73:     else counts.unknown += 1;
74:   }
75: 
76:   return { changes: classified, counts };
77: }
78: 
79: export { COMPATIBILITY };
80: export default classifyChanges;

