// Throwaway smoke test for GET /api/specs/diff (extended with classification).
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const base = 'http://127.0.0.1:3000';
const here = fileURLToPath(new URL('..', import.meta.url)); // backend/
const readSpec = (p) => readFileSync(path.join(here, '..', 'specs', p), 'utf8');

async function post(p, body) {
  const res = await fetch(base + p, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });
  return { status: res.status, body: await res.json() };
}

async function get(p) {
  const res = await fetch(base + p);
  return { status: res.status, body: await res.json() };
}

async function seed(name, owner, specPaths) {
  const svc = await post('/api/services', { name, owner, description: 'smoke test' });
  if (svc.status !== 201) throw new Error(`service create failed: ${JSON.stringify(svc.body)}`);
  const versions = [];
  for (let i = 0; i < specPaths.length; i += 1) {
    const up = await post('/api/specs/upload', {
      serviceId: svc.body.data.id,
      versionLabel: `v${i + 1}`,
      content: readSpec(specPaths[i]),
    });
    if (up.status !== 201) throw new Error(`upload failed: ${JSON.stringify(up.body)}`);
    versions.push(up.body.data);
  }
  return { svc: svc.body.data, versions };
}

